import { cookies, headers } from 'next/headers'

const DEFAULT_THEME = 'light'
const DEFAULT_LANGUAGE = 'en'

// Picks the highest-weighted language tag from an Accept-Language header,
// e.g. "fr-CH, fr;q=0.9, en;q=0.8" -> "fr-CH".
function getPreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return DEFAULT_LANGUAGE

  const languages = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params.find((p) => p.trim().startsWith('q='))
      const q = qParam ? parseFloat(qParam.trim().slice(2)) : 1
      return { tag: tag.trim(), q: Number.isNaN(q) ? 0 : q }
    })
    .filter(({ tag, q }) => tag && tag !== '*' && q > 0)
    .sort((a, b) => b.q - a.q)

  return languages[0]?.tag ?? DEFAULT_LANGUAGE
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value || DEFAULT_THEME
  const language = getPreferredLanguage(headersList.get('accept-language'))

  return (
    <section>
      <p>
        Current theme: <strong data-testid="theme">{theme}</strong>
      </p>
      <p>
        Preferred language: <strong data-testid="language">{language}</strong>
      </p>
    </section>
  )
}

